// A transparent, offline-capable planner for the interactive preview and no-server use.
// The Render app uses backend/planner.py. Both read the same catalog and cost model.
const categories=['beaches','nature','culture','adventure','food','nightlife','shopping'];
const enc=encodeURIComponent;
export const mapURL=query=>`https://www.google.com/maps/search/?api=1&query=${enc(query)}`;
export const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
export function addDays(iso,n){const d=new Date(iso+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
export function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function title(s){return s.replace(/\b\w/g,x=>x.toUpperCase())}
export function parsePrompt(prompt,catalog){
 const text=prompt.toLowerCase(),result={};
 if(/[$€£]|\b(?:usd|eur|gbp|dollars|euros|pounds)\b/.test(text))throw Error('This version budgets in INR. Please enter your total budget in ₹.');
 let dest=text.match(/(?:trip|vacation|holiday|travel)\s+(?:to|in)\s+([a-z][a-z .'-]+?)(?=\s+(?:for|from|in|with|on|during|budget)\b|[.,;!]|$)/)||text.match(/(?:\d+[- ]days?\s+)([a-z][a-z .'-]+?)(?:\s+trip|\s+vacation)/);
 if(dest)result.destination=title(dest[1].trim());
 if(!result.destination){const withoutOrigin=text.replace(/\bfrom\s+[a-z .'-]+?(?=\s+(?:in|for|to|on|with|during)\b|[.,;!]|$)/g,'');const known=catalog.find(p=>new RegExp(`\\b${p.name.toLowerCase()}\\b`).test(withoutOrigin));if(known)result.destination=known.name}
 const origin=text.match(/\bfrom\s+([a-z][a-z .'-]+?)(?=\s+(?:in|for|to|on|with|during|budget)\b|[.,;!]|$)/);if(origin)result.origin=title(origin[1].trim());
 for(const [regex,key] of [[/(\d+)\s*[- ]?\s*days?/,'days'],[/(\d+)\s*(?:people|persons|adults|travellers|travelers)/,'travelers']]){let m=text.match(regex);if(m)result[key]=Number(m[1])}
 const budget=text.match(/(?:₹|inr\s*|budget\s*(?:of|is|:)?\s*)([\d,]+(?:\.\d+)?)\s*(lakh|lac|lakhs|lacs|k|crore)?/);
 if(budget)result.budget=Math.round(Number(budget[1].replaceAll(',',''))*({lakh:100000,lac:100000,lakhs:100000,lacs:100000,k:1000,crore:10000000}[budget[2]]||1));
 const exact=text.match(/\b(20\d\d-\d\d-\d\d)\b/);
 if(exact)result.start_date=exact[1];else{const months=['january','february','march','april','may','june','july','august','september','october','november','december'];for(let i=0;i<12;i++){const m=text.match(new RegExp(`\\b${months[i]}(?:\\s+(20\\d\\d))?\\b`));if(m){const now=new Date();let year=m[1]?Number(m[1]):now.getFullYear()+(i<now.getMonth()||(i===now.getMonth()&&now.getDate()>1)?1:0);result.start_date=`${year}-${String(i+1).padStart(2,'0')}-01`;break}}}
 const interests=categories.filter(x=>text.includes(x)||(x==='beaches'&&text.includes('beach')));if(interests.length)result.interests=interests;
 if(['relax','slow','not exhausting',"don't make",'easy pace'].some(x=>text.includes(x)))result.pace='relaxed';else if(text.includes('packed')||text.includes('busy schedule'))result.pace='packed';else if(text.includes('balanced'))result.pace='balanced';
 if(text.includes('luxury')||text.includes('5-star'))result.comfort='luxury';else if(text.includes('hostel')||text.includes('budget hotel'))result.comfort='value';
 return result;
}
export function genericDestination(name){return{id:'custom',name,country:'To confirm',iata:null,lat:null,lon:null,tagline:'Your trip, at your pace',description:'A flexible starting point for your adventure',room:6500,food:2200,transport:1400,activity:1600,flight:45000,image:'/assets/terraces.jpg',image_subject:'Travel inspiration',areas:['Central area'],places:[]}}
export function estimateBudget(b,d){
 const scale={value:.65,comfort:1,luxury:2}[b.comfort],rooms=Math.ceil(b.travelers/2),nights=Math.max(0,b.days-1);
 const items=[
 {id:'flights',label:'Return flights',amount:b.origin.toLowerCase()===b.destination.toLowerCase()?0:d.flight*b.travelers,detail:`${b.travelers} people · route estimate`},
 {id:'stays',label:'Accommodation',amount:Math.round(d.room*scale)*rooms*nights,detail:`${rooms} room(s) × ${nights} nights`},
 {id:'food',label:'Food & cafés',amount:Math.round(d.food*scale)*b.travelers*b.days,detail:`${b.travelers} people × ${b.days} days`},
 {id:'transport',label:'Local transport',amount:Math.round(d.transport*Math.ceil(b.travelers/4))*b.days,detail:'Shared rides / local transport allowance'},
 {id:'activities',label:'Experiences',amount:Math.round(d.activity*scale)*b.travelers*Math.max(0,b.days-2),detail:'Activity allowance for full days'}];
 const subtotal=items.reduce((s,x)=>s+x.amount,0);items.push({id:'buffer',label:'Contingency',amount:Math.round(subtotal*.15),detail:'15% for changes and incidental costs'});
 const total=items.reduce((s,x)=>s+x.amount,0);
 return{currency:'INR',total,target:b.budget,remaining:b.budget-total,per_person:Math.round(total/b.travelers),rooms,nights,nightly_rate:Math.round(d.room*scale),items,status:total<=b.budget?'within':'over',basis:'Illustrative planning estimates, not quotes. Flights use a broad India-origin baseline; no route or fare has been priced. Rooms assume two guests each. Visa fees, insurance and shopping are excluded. Confirm all costs before booking.'};
}
export function buildSchedule(b,d){
 const grouped={};d.places.forEach(p=>(grouped[p.area]??=[]).push(p));
 const ordered=Object.values(grouped).sort((a,c)=>c.filter(p=>b.interests.includes(p.category)).length-a.filter(p=>b.interests.includes(p.category)).length).flatMap(g=>g.sort((a,c)=>Number(b.interests.includes(c.category))-Number(b.interests.includes(a.category))));
 let cursor=0;return Array.from({length:b.days},(_,index)=>{const first=index===0,last=index===b.days-1,count=first||last?1:{relaxed:2,balanced:3,packed:4}[b.pace],selected=ordered.slice(cursor,cursor+count);cursor+=selected.length;let items=[];
 if(first)items.push({time:'Flexible',title:'Arrive, settle in & take a breath',category:'travel',area:d.areas[0],description:'Keep this block flexible around actual arrival and check-in times.',duration:'Allow 2–3 hours',optional:false});
 selected.forEach((p,j)=>items.push({time:p.category==='nightlife'?'19:30':first?'16:00':last?'09:00':['10:00','15:00','17:30','19:30'][j],title:p.name,area:p.area,category:p.category,description:p.description,duration:'Allow 1–2 hours',optional:first||last||p.category==='nightlife',map_url:mapURL(p.name+', '+b.destination)}));
 if(!first&&!last){items.push({time:'13:00',title:'Lunch & proper downtime',category:'rest',area:selected[0]?.area||d.areas[0],description:'Keep this window free for lunch, a café or a hotel break.',duration:'2 hours',optional:false});if(!selected.length)items.push({time:'10:00',title:'An open day to make your own',category:'free',area:d.areas[0],description:'Explore a neighbourhood, revisit a favourite spot, or ask the copilot for ideas. No new sight has been verified for this day.',duration:'Your choice',optional:true})}
 if(last)items.push({time:'Flexible',title:'Check out & head home',category:'travel',area:'Departure',description:'Work backwards from your confirmed departure time and the operator’s check-in guidance.',duration:'Allow transfer time',optional:false});
 items=[...items.filter(i=>i.time==='Flexible'&&i.title.startsWith('Arrive')),...items.filter(i=>i.time!=='Flexible').sort((a,c)=>a.time.localeCompare(c.time)),...items.filter(i=>i.time==='Flexible'&&!i.title.startsWith('Arrive'))];
 return{day:index+1,date:b.start_date?addDays(b.start_date,index):null,title:first?'Touch down & slow down':last?'One last little adventure':selected[0]?selected[0].area+', at your pace':'Leave a little room for serendipity',area:selected[0]?.area||d.areas[0],items,note:'Suggested times. Confirm access, opening hours and travel times before heading out.'};});
}
function makeTravelOptions(b,d,budget){
 const flightAllowance=budget.items.find(x=>x.id==='flights').amount,localAllowance=budget.items.find(x=>x.id==='transport').amount;
 const flightURL=`https://www.google.com/travel/flights?q=${enc(`return flights from ${b.origin} to ${b.destination} ${b.start_date||'flexible dates'} for ${b.travelers} travelers`)}`;
 const flights=flightAllowance?[['Best overall',1,'Balanced target for fare, stops and timing',91],['Lowest-price target',.82,'Try nearby dates and longer connections',86],['Fewer-stops target',1.14,'Prioritise a simpler route and shorter journey',82]].map((x,i)=>({id:`estimate-${i+1}`,label:x[0],estimate:Math.round(flightAllowance*x[1]),why:x[2],score:x[3],currency:'INR',travelers:b.travelers,source:'VoyageOS planning estimate',source_mode:'estimate',live:false,itineraries:[],url:flightURL})):[];
 const cities=new Set(['kolkata','delhi','new delhi','mumbai','bengaluru','bangalore','chennai','hyderabad','goa','manali','jaipur','pune','ahmedabad','lucknow','varanasi','kochi','cochin']);
 const domestic=d.country.toLowerCase()==='india'&&cities.has(b.origin.toLowerCase());
 const rail={available:domestic,name:'Indian Railways',label:domestic?'Best for value':'Not suitable for this route',description:domestic?'Compare classes and verified train availability on IRCTC.':'This planner found no sensible direct rail handoff for the selected route.',estimate:domestic?Math.round(Math.max(600,localAllowance*.55)):null,url:'https://www.irctc.co.in/nget/train-search',search_url:`https://www.google.com/search?q=${enc(`${b.origin} to ${b.destination} trains IRCTC`)}`,source_mode:domestic?'estimate':'not_applicable'};
 const road={available:domestic,name:'Intercity road',label:domestic?'Flexible alternative':'Local transfers only',description:domestic?'Compare bus or intercity cab time against the train before choosing.':'Use road travel for airport and local transfers after arrival.',estimate:domestic?Math.round(Math.max(900,localAllowance*.85)):null,url:`https://www.google.com/maps/dir/?api=1&origin=${enc(b.origin)}&destination=${enc(b.destination)}`,source_mode:domestic?'estimate':'route_guidance'};
 const cabs=[['Airport pickup','Arrival-safe','Compare a pre-booked pickup with the airport taxi desk.',.18,mapURL(`airport transfer in ${b.destination}`)],['Ride-hailing','On demand','Check availability, surge pricing and pickup zones after landing.',.12,`https://m.uber.com/ul/?action=setPickup&pickup=my_location&dropoff%5Bformatted_address%5D=${enc(b.destination)}`],['Day cab','Best for clusters','Useful when several stops are outside the public-transport core.',.55,`https://www.google.com/search?q=${enc(`day cab in ${b.destination}`)}`]].map((x,i)=>({name:x[0],label:x[1],description:x[2],estimate:Math.round(Math.max([500,350,1200][i],localAllowance*x[3])),url:x[4]}));
 return{flights,transport:{rail,road,cabs},flightURL};
}
function makeAgentReport(b,d,budget,hotels,flights,transport){
 const over=budget.remaining<0,score=Math.max(54,Math.min(96,(d.id==='custom'?72:88)+(over?-18:5)));
 const agents=[['brief','Intent Agent','Understands your constraints','rules',`Locked ${b.days} days, ${b.travelers} travelers and a ${money(b.budget)} ceiling.`],['route','Route Agent','Ranks ways to reach the destination','estimate',`Ranked ${flights.length} flight choices and checked rail/road fit.`],['stay','Stay Agent','Compares areas and properties','estimate',`Shortlisted ${hotels.length} stays across practical neighbourhoods.`],['mobility','Mobility Agent','Plans airport and local movement','route guidance',`Prepared ${transport.cabs.length} local mobility choices and transfer handoffs.`],['itinerary','Itinerary Agent','Groups nearby experiences','constraint engine',`Built ${b.days} paced days with protected rest and light travel days.`],['budget','Budget Agent','Builds the full-trip cost model','deterministic',`Costed the whole group with a 15% contingency: ${money(budget.total)}.`],['critic','Critic Agent','Challenges weak assumptions','validation',over?'Flagged the budget gap and cheaper levers.':'Checked the plan against budget, pace and source quality.']].map(x=>({id:x[0],name:x[1],role:x[2],status:'complete',mode:x[3],summary:x[4]}));
 const recommendation={score,headline:`Best fit: ${flights.length?'Flight':'Local transport'} + ${b.comfort} stay + ${b.pace} days`,reason:over?'This is the strongest route match, but the budget needs one deliberate trade-off before booking.':'This combination protects your pace while keeping the largest costs visible.',budget_status:over?'over':'within',savings:['Compare departures one or two days either side of your date before paying.',`Start with ${d.areas[0]} to reduce repeated local transfers.`,'Choose refundable options until the route and leave dates are final.'],confidence:score>=85?'high':'medium'};
 return{agents,recommendation};
}
export function makeLocalPlan(request,catalog){
 const {prompt,...overrides}=request,parsed=parsePrompt(prompt,catalog),b={origin:'Your city',days:6,travelers:2,budget:140000,start_date:null,pace:'relaxed',comfort:'comfort',interests:['nature','food'],...parsed,...overrides};
 if(!b.destination||b.destination.length<2)throw Error('Add a destination in Trip details, or write “Plan a trip to Bali for 6 days”.');
 if(!Number.isInteger(b.days)||b.days<1||b.days>30)throw Error('Choose a trip length between 1 and 30 days.');
 if(!Number.isInteger(b.travelers)||b.travelers<1||b.travelers>20)throw Error('Choose between 1 and 20 travelers.');
 if(!Number.isInteger(b.budget)||b.budget<1000||b.budget>10000000)throw Error('Enter an INR budget between ₹1,000 and ₹1 crore.');
 if(!['relaxed','balanced','packed'].includes(b.pace)||!['value','comfort','luxury'].includes(b.comfort))throw Error('Choose a valid travel pace and comfort level.');
 if(b.start_date&&(!/^\d{4}-\d{2}-\d{2}$/.test(b.start_date)||Number.isNaN(Date.parse(b.start_date))||new Date(b.start_date+'T12:00:00Z').toISOString().slice(0,10)!==b.start_date||b.start_date<today()))throw Error('Choose a valid future departure date in Trip details.');
 const d=structuredClone(catalog.find(p=>p.name.toLowerCase()===b.destination.toLowerCase())||genericDestination(b.destination)),budget=estimateBudget(b,d),warnings=['Preview mode: this plan was generated in your browser. AI and live providers require the FastAPI app.'];
 if(d.id==='custom')warnings.push('This destination has no built-in sight list. This is a flexible outline; add Groq for destination-specific suggestions.');
 if(budget.remaining<0)warnings.push(`This estimate exceeds your budget by ${money(-budget.remaining)}. Try value stays, fewer nights or another destination.`);
 if(b.start_date&&!request.start_date&&/january|february|march|april|may|june|july|august|september|october|november|december/i.test(prompt))warnings.push('A month-only request uses its first day. Confirm your exact dates in Trip details.');
 warnings.push('Entry requirements, activity suitability, transport schedules and opening hours are not verified. Review official sources before booking.');
 const hotels=d.areas.slice(0,3).map((area,i)=>{let params=new URLSearchParams({ss:`${area}, ${b.destination}`,group_adults:b.travelers,no_rooms:budget.rooms});if(b.start_date&&b.days>1){params.set('checkin',b.start_date);params.set('checkout',addDays(b.start_date,b.days-1))}return{name:`${['Boutique stay','A comfortable base','A little extra comfort'][i]} in ${area}`,area,source:'Stay inspiration',real_property:false,image:i%2?'/assets/villa.jpg':'/assets/hotel.jpg',image_subject:'Illustrative hotel photo',nightly_estimate:Math.round(budget.nightly_rate*[1,.8,1.25][i]),description:['Look for a well-located stay with easy access to your planned stops.','Prioritise a comfortable room and practical transport links.','Compare amenities, recent reviews and cancellation terms.'][i],url:'https://www.booking.com/searchresults.html?'+params}});
 const options=makeTravelOptions(b,d,budget),report=makeAgentReport(b,d,budget,hotels,options.flights,options.transport);
 return{id:crypto.randomUUID(),created_at:new Date().toISOString(),mode:d.id==='custom'?'flexible':'preview',brief:b,destination:d,days:buildSchedule(b,d),budget,hotels,flights:options.flights,transport:options.transport,agents:report.agents,recommendation:report.recommendation,flight_search_url:options.flightURL,transfer_url:mapURL(`airport transfer ${b.destination}`),weather:null,weather_note:'Forecasts are available only within the next 16 days; later dates are not a weather forecast.',warnings,packing:['Travel documents & copies','Cards and some local cash','Charger & adapter','Comfortable walking shoes','Weather-appropriate layers','Personal essentials'],sources:[{name:'Google Maps · verify places',url:mapURL(b.destination)},{name:'Open-Meteo / GeoNames',url:'https://open-meteo.com/'},{name:'Wikipedia · destination context',url:`https://en.wikipedia.org/wiki/${enc(b.destination)}`}]};
}
export function localChat(message,plan){const text=message.toLowerCase(),b=plan.brief;if(/budget|cheap|cost|save/.test(text))return`Your illustrative total is ${money(plan.budget.total)}, including a 15% contingency. Compare flexible flight dates, choose value stays, and group sights in the same area. Use Trip details to change comfort or trip length and regenerate. These are planning allowances, not bookable prices.`;if(/rain|weather/.test(text))return'Keep an indoor alternative for each outdoor day: a museum, café or local cultural visit. Check the forecast close to departure and local advisories before weather-sensitive activities. Live forecasts require the FastAPI app and dates within 16 days.';if(/relax|tired|slow|exhaust/.test(text))return'Choose Relaxed in Trip details and regenerate. Full days will have at most two suggested sights and a two-hour lunch/rest block, with light arrival and departure days. Transfer and activity durations still need checking.';if(/hotel|stay/.test(text))return`Compare accommodation in ${plan.destination.areas.join(', ')}. Prioritise location, recent reviews, room occupancy and cancellation terms. Stay inspiration cards link to searches; their photos do not depict a specific bookable property.`;return`For ${b.destination}, this preview copilot can help with budget, pace, stays and rainy-day alternatives. Deploy the FastAPI app with Groq for open-ended questions. Use Trip details to change and regenerate your itinerary.`}
